/* xu117 passive native gate notifier/handshake trace. No VPI writes/forces. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "vpi_user.h"
#define LIMIT 512
#define START_FS UINT64_C(9359300000000)
#define STOP_FS UINT64_C(9359500000000)
static const char *const target_name="tb_xu_soc_ppa.dut.u_soc.u_e203_subsys_top.u_e203_subsys_main.u_e203_subsys_mems.u_sirv_mem_fab.u_sirv_gnrl_icb_buffer.u_sirv_gnrl_rsp_fifo.dp_gt0.vec_31_dfflr.qout_r_reg[0]";
static const char *const fifo_name="tb_xu_soc_ppa.dut.u_soc.u_e203_subsys_top.u_e203_subsys_main.u_e203_subsys_mems.u_sirv_mem_fab.u_sirv_gnrl_icb_buffer.u_sirv_gnrl_rsp_fifo";
static const char *const accel_name="tb_xu_soc_ppa.dut.u_soc.u_e203_subsys_top.u_e203_subsys_main.u_e203_subsys_perips.u_accel_icb_slave";
static vpiHandle nodes[LIMIT];static char *names[LIMIT],*roles[LIMIT];
static s_cb_data records[LIMIT];static s_vpi_time times[LIMIT];static s_vpi_value values[LIMIT];
static unsigned count,cell_count,fifo_count,shared_count,accel_count,failed;static uint64_t serial,events;
static void canonical(const char *in,char *out,size_t n){size_t k=0;while(*in){unsigned char c=(unsigned char)*in++;if(c=='\\'||isspace(c))continue;if(k+1>=n){++failed;break;}out[k++]=(char)c;}out[k]=0;}
static uint64_t tick(void){s_vpi_time t;memset(&t,0,sizeof(t));t.type=vpiSimTime;vpi_get_time(NULL,&t);return((uint64_t)t.high<<32)|(uint32_t)t.low;}
static void snapshot(unsigned i,const char *reason){s_vpi_value v;unsigned width=(unsigned)vpi_get(vpiSize,nodes[i]);uint64_t t=tick();uint32_t a0=0,b0=0,a1=0,b1=0;memset(&v,0,sizeof(v));v.format=vpiVectorVal;vpi_get_value(nodes[i],&v);if(v.value.vector&&width>0&&width<=64){a0=(uint32_t)v.value.vector[0].aval;b0=(uint32_t)v.value.vector[0].bval;if(width>32){a1=(uint32_t)v.value.vector[1].aval;b1=(uint32_t)v.value.vector[1].bval;}}else{++failed;return;}vpi_printf("XU_CAUSAL117_EVENT serial=%llu tick_fs=%llu reason=%s role=%s bits=%u aval=%08x%08x bval=%08x%08x name=%s\n",(unsigned long long)++serial,(unsigned long long)t,reason,roles[i],width,a1,a0,b1,b0,names[i]);}
static PLI_INT32 changed(p_cb_data cb){unsigned i=(unsigned)(uintptr_t)cb->user_data;uint64_t t=tick();if(i>=count){++failed;return 0;}if(t>=START_FS&&t<=STOP_FS){++events;snapshot(i,"value_change");}return 0;}
static void bind(vpiHandle h,const char *role){unsigned i;const char *s;char full[8192];if(!h||vpi_get(vpiSize,h)<1||vpi_get(vpiSize,h)>64){++failed;vpi_printf("XU_CAUSAL117_BIND_REJECT role=%s reason=missing_or_width\n",role);return;}for(i=0;i<count;++i)if(vpi_compare_objects(h,nodes[i]))return;if(count>=LIMIT){++failed;return;}i=count++;nodes[i]=h;roles[i]=strdup(role);s=vpi_get_str(vpiFullName,h);canonical(s?s:"",full,sizeof(full));names[i]=strdup(full);memset(&records[i],0,sizeof(records[i]));memset(&times[i],0,sizeof(times[i]));memset(&values[i],0,sizeof(values[i]));times[i].type=vpiSuppressTime;values[i].format=vpiSuppressVal;records[i].reason=cbValueChange;records[i].cb_rtn=changed;records[i].obj=h;records[i].time=&times[i];records[i].value=&values[i];records[i].user_data=(PLI_BYTE8*)(uintptr_t)i;if(!vpi_register_cb(&records[i]))++failed;vpi_printf("XU_CAUSAL117_BIND role=%s type=%d bits=%d name=%s\n",role,vpi_get(vpiType,h),vpi_get(vpiSize,h),names[i]);}
static void walk(vpiHandle mod){vpiHandle iterator,child;const char *s=vpi_get_str(vpiFullName,mod);char full[8192];canonical(s?s:"",full,sizeof(full));if(strcmp(full,target_name)==0){const char *ref=vpi_get_str(vpiDefName,mod);++cell_count;vpi_printf("XU_CAUSAL117_TARGET name=%s ref=%s\n",full,ref?ref:"<null>");iterator=vpi_iterate(vpiNet,mod);if(iterator)while((child=vpi_scan(iterator))!=NULL)bind(child,"target_native_net");iterator=vpi_iterate(vpiReg,mod);if(iterator)while((child=vpi_scan(iterator))!=NULL)bind(child,"target_native_reg");}if(strcmp(full,fifo_name)==0){++fifo_count;iterator=vpi_iterate(vpiNet,mod);if(iterator)while((child=vpi_scan(iterator))!=NULL){int width=vpi_get(vpiSize,child);if(width>=1&&width<=64)bind(child,"fifo_native_net");}iterator=vpi_iterate(vpiReg,mod);if(iterator)while((child=vpi_scan(iterator))!=NULL){int width=vpi_get(vpiSize,child);if(width>=1&&width<=64)bind(child,"fifo_native_reg");}}if(strcmp(full,"tb_xu_soc_ppa.dut.u_shared")==0){static const char *p[]={"clk","rst_n","cmd_valid","cmd_ready","cmd_read","cmd_addr","cmd_wdata","cmd_wmask","rsp_valid","rsp_ready","rsp_rdata","rsp_err"};unsigned i;++shared_count;for(i=0;i<sizeof(p)/sizeof(p[0]);++i)bind(vpi_handle_by_name((PLI_BYTE8*)p[i],mod),"actual_shared_port");}if(strcmp(full,accel_name)==0){++accel_count;bind(vpi_handle_by_name((PLI_BYTE8*)"clk",mod),"actual_accel_clock");bind(vpi_handle_by_name((PLI_BYTE8*)"rst_n",mod),"actual_accel_reset");}iterator=vpi_iterate(vpiModule,mod);if(iterator)while((child=vpi_scan(iterator))!=NULL)walk(child);}
static PLI_INT32 start(p_cb_data unused){vpiHandle root;(void)unused;root=vpi_handle_by_name((PLI_BYTE8*)"tb_xu_soc_ppa.dut",NULL);if(root)walk(root);else ++failed;if(cell_count!=1||fifo_count!=1||shared_count!=1||accel_count!=1)++failed;vpi_printf("XU_CAUSAL117_READY target_cells=%u fifo_modules=%u shared_modules=%u accel_modules=%u observed_nodes=%u failed=%u start_fs=%llu stop_fs=%llu writes=0 forces=0 timing_controls_changed=0 NOT_FUNCTIONAL_OR_150MHZ_OR_ENERGY_QUALIFIED\n",cell_count,fifo_count,shared_count,accel_count,count,failed,(unsigned long long)START_FS,(unsigned long long)STOP_FS);return 0;}
static PLI_INT32 done(p_cb_data unused){unsigned i;(void)unused;for(i=0;i<count;++i)snapshot(i,"end_snapshot");vpi_printf("XU_CAUSAL117_END events_in_slice=%llu observed_nodes=%u failed=%u final_tick_fs=%llu writes=0 forces=0 NOT_FUNCTIONAL_OR_150MHZ_OR_ENERGY_QUALIFIED\n",(unsigned long long)events,count,failed,(unsigned long long)tick());return 0;}
void xu_causal117_register(void){static s_cb_data begin,end;memset(&begin,0,sizeof(begin));memset(&end,0,sizeof(end));begin.reason=cbStartOfSimulation;begin.cb_rtn=start;end.reason=cbEndOfSimulation;end.cb_rtn=done;if(!vpi_register_cb(&begin)||!vpi_register_cb(&end))++failed;}
void(*vlog_startup_routines[])(void)={xu_causal117_register,NULL};
